using Microsoft.Extensions.AI;

public class TopicHelper(IChatClient chat)
{
    public async Task<string> ExplainAsync(string topic, CancellationToken ct)
    {
        List<ChatMessage> messages =
        [
            new(ChatRole.System, "You explain programming topics to first-year students in three short sentences."),
            new(ChatRole.User, $"Explain: {topic}"),
        ];

        var response = await chat.GetResponseAsync(messages, cancellationToken: ct);
        return response.Text;
    }
}

using System.Numerics.Tensors;
using Microsoft.Extensions.AI;

public class NotesSearch(IEmbeddingGenerator<string, Embedding<float>> embeddings, IChatClient chat)
{
    public async Task<string> AskAsync(string question, IReadOnlyList<(string Text, float[] Vector)> notes)
    {
        var q = await embeddings.GenerateVectorAsync(question);

        var context = notes
            .OrderByDescending(n => TensorPrimitives.CosineSimilarity(q.Span, n.Vector))
            .Take(3)
            .Select(n => n.Text);

        var prompt = $"Answer only from these notes. If they do not contain the answer, say so.\n\n" +
                     $"{string.Join("\n---\n", context)}\n\nQuestion: {question}";

        return (await chat.GetResponseAsync(prompt)).Text;
    }
}

