// A background service reads unsent outbox rows, publishes them to the broker,
// and marks them as sent.

using System.Text;
using System.Text.Json;
using RabbitMQ.Client;

var factory = new ConnectionFactory { HostName = "localhost" };
await using var connection = await factory.CreateConnectionAsync();
await using var channel = await connection.CreateChannelAsync();

await channel.ExchangeDeclareAsync("enrollments", ExchangeType.Fanout, durable: true);

var body = Encoding.UTF8.GetBytes(JsonSerializer.Serialize(new { studentId = 1, courseId = 2 }));
var props = new BasicProperties { Persistent = true };
await channel.BasicPublishAsync("enrollments", routingKey: "", mandatory: false, basicProperties: props, body: body);

await channel.QueueDeclareAsync("billing", durable: true, exclusive: false, autoDelete: false);
await channel.QueueBindAsync("billing", "enrollments", routingKey: "");
await channel.BasicQosAsync(prefetchSize: 0, prefetchCount: 10, global: false);

var consumer = new AsyncEventingBasicConsumer(channel);
consumer.ReceivedAsync += async (_, ea) =>
{
    var json = Encoding.UTF8.GetString(ea.Body.Span);
    await CreateInvoiceAsync(json);                                     // the real work
    await channel.BasicAckAsync(ea.DeliveryTag, multiple: false);       // only now is it done
};

await channel.BasicConsumeAsync("billing", autoAck: false, consumer: consumer);

// The queue sends rejected messages to the dead-letter exchange
await channel.QueueDeclareAsync("billing", durable: true, exclusive: false, autoDelete: false,
    arguments: new Dictionary<string, object?> { ["x-dead-letter-exchange"] = "enrollments.dead" });

consumer.ReceivedAsync += async (_, ea) =>
{
    var id = ea.BasicProperties.MessageId!;
    if (await AlreadyProcessedAsync(id)) { await channel.BasicAckAsync(ea.DeliveryTag, false); return; }

    try
    {
        await CreateInvoiceAsync(Encoding.UTF8.GetString(ea.Body.Span));
        await MarkProcessedAsync(id);
        await channel.BasicAckAsync(ea.DeliveryTag, false);
    }
    catch (Exception)
    {
        // A bad message: do not requeue it forever, let it go to the dead-letter queue
        await channel.BasicNackAsync(ea.DeliveryTag, multiple: false, requeue: false);
    }
};
